/** Durable brand values shared by the Host schema and Client presentation. */
export interface Brand {
  name: string
  initials: string
  /** Accent color (#rrggbb) applied to the DSH brand-primary tokens. */
  accent: string
  /** Body text color (#rrggbb); empty keeps the theme default on both modes. */
  text: string
  /** Primary gradient start (#rrggbb) used on brand marks. */
  gradientFrom: string
  /** Primary gradient end (#rrggbb) used on brand marks. */
  gradientTo: string
  /** One-line vision statement shown as the hero mark tooltip. */
  vision: string
  /** Ecosystem site URL shown on the brand settings page. */
  site: string
  /** ICP filing number (Chinese mainland compliance); empty hides the legal line. */
  icp: string
  /** Logo as a `data:image/*` data URL; empty falls back to the initials mark. */
  logo: string
}
/** Default product identity used until Host settings arrive. */
export const defaultBrand: Brand = {
  name: 'XYAI Studio',
  initials: 'XY',
  accent: '#1565c0',
  text: '',
  gradientFrom: '#1565c0',
  gradientTo: '#0288d1',
  vision: "帮你把行业经验，变成可复用、可商用的人工智能生产力",
  site: '',
  icp: '',
  logo: "data:image/png;base64,",
}
/** Brand fields in save/reset order. */
export const BRAND_FIELDS = ['name', 'initials', 'accent', 'text', 'gradientFrom', 'gradientTo', 'vision', 'site', 'icp', 'logo'] as const
/** Longest accepted ICP filing number. */
export const MAX_ICP_LENGTH = 60
/** Longest accepted ecosystem-sites text (comma-separated list). */
export const MAX_SITES_LENGTH = 400
/** Longest accepted logo data URL (client resizes uploads to fit). */
export const MAX_LOGO_DATAURL = 100_000
